const doAlgebra = (operator, operand) => {
  let expression = "";
  for (let i = 0; i < operator.length; i++) {
    expression += operand[i] + " " + operator[i].replace("//", "/").replace("**", "**") + " ";
  }
  expression += operand[operand.length - 1];

  // To handle floor division specifically as requested (//), 
  // we can't simply use eval() because JS / is float division.
  // However, the standard way to evaluate a string expression with 
  // specific operator precedence in JS is using a Function constructor or eval.
  // Since the prompt asks for "Floor division ( // )", we must ensure 
  // that division results are floored.

  // A robust way to handle the specific operators provided:
  const ops = {
    '+': (a, b) => a + b,
    '-': (a, b) => a - b,
    '*': (a, b) => a * b,
    '//': (a, b) => Math.floor(a / b),
    '**': (a, b) => Math.pow(a, b)
  };

  // To respect standard order of operations (PEMDAS), we build a string 
  // that JS understands, but replace // with a custom function or 
  // handle it via a parser. For simplicity and correctness regarding 
  // the specific operators:

  let tokens = [];
  for (let i = 0; i < operand.length; i++) {
    tokens.push(operand[i]);
    if (i < operator.length) {
      tokens.push(operator[i]);
    }
  }

  // Handle Exponentiation (Right-to-Left)
  for (let i = tokens.length - 1; i >= 0; i--) {
    if (tokens[i] === '**') {
      tokens.splice(i - 1, 3, Math.pow(tokens[i - 1], tokens[i + 1]));
      i--; 
    }
  }

  // Handle Multiplication and Floor Division (Left-to-Right)
  for (let i = 0; i < tokens.length; i++) {
    if (tokens[i] === '*' || tokens[i] === '//') {
      const left = tokens[i - 1];
      const right = tokens[i + 1];
      const res = tokens[i] === '*' ? left * right : Math.floor(left / right);
      tokens.splice(i - 1, 3, res);
      i--;
    }
  }

  // Handle Addition and Subtraction (Left-to-Right)
  let result = tokens[0];
  for (let i = 1; i < tokens.length; i += 2) {
    const op = tokens[i];
    const val = tokens[i + 1];
    if (op === '+') result += val;
    if (op === '-') result -= val;
  }

  return result;
};

