const solve = (s) => {
  let hasLetter = false;
  let result = "";

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    if (/[a-zA-Z]/.test(char)) {
      hasLetter = true;
      if (char === char.toUpperCase()) {
        result += char.toLowerCase();
      } else {
        result += char.toUpperCase();
      }
    } else {
      result += char;
    }
  }

  if (!hasLetter) {
    return s.split("").reverse().join("");
  }

  return result;
};

